import { NextResponse } from 'next/server'
import { requireAdmin } from '@/lib/apiAuth'
import { resolveStyleSet } from '@/lib/styleSets/data'

/**
 * The firm formatting rules the pane applies to the open document.
 *
 * Same `StyleSetSettings` the generator applies at render time, so a document
 * formatted in Word and a document generated by Cornerstone agree on font,
 * title size, and subsection indents rather than drifting apart.
 *
 * `?id=` selects a specific style set; omitted, `resolveStyleSet` returns the
 * default (currently the legacy Garamond-only sweep).
 */
export async function GET(req: Request) {
  const auth = await requireAdmin(req)
  if (auth.err) return auth.err

  const id = new URL(req.url).searchParams.get('id')

  try {
    const settings = await resolveStyleSet(id)
    return NextResponse.json({ id, settings }, { headers: { 'Cache-Control': 'no-store' } })
  } catch (err) {
    return NextResponse.json(
      { error: err instanceof Error ? err.message : 'Failed to load style set' },
      { status: 500 },
    )
  }
}
